/**
 * Issue business rules: authorization, per-project issue quota, numbering, status transitions and the events every other concern reacts to.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope, emit, wouldExceedLimit, assertNotArchived
 */
import { wouldExceedLimit } from "@/config/plan-limits";
import { emit } from "@/lib/event-bus";
import { assertCan } from "@/lib/permissions";
import { assertNotArchived } from "@/lib/soft-delete";
import { assertOrgScope } from "@/lib/tenant";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as labelRepo from "@/server/repositories/label-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as projectRepo from "@/server/repositories/project-repository";
import * as commentRepo from "@/server/repositories/comment-repository";
import * as attachmentRepo from "@/server/repositories/attachment-repository";
import {
  actorEnvelope,
  issueResource,
  orgResource,
  projectResource,
  requireFound,
} from "./_support";
import type {
  AssignIssueInput,
  ChangeIssueStatusInput,
  CreateIssueInput,
  IssueFilterInput,
  MoveIssueInput,
  UpdateIssueInput,
} from "@/schemas/issue";
import type { IssueId, OrgId, Page, ProjectId } from "@/types/common";
import type { Issue, IssueBoardColumn, IssueWithRelations } from "@/types/issue";
import type { Actor } from "@/types/member";

/**
 * Creates an issue after four gates: tenant scope, the `issue:create`
 * permission, a live parent project and the plan's per-project issue quota.
 * Only then is a number allocated and `issue.created` published — everything
 * reactive (notifications, search, webhooks, the audit log) hangs off that.
 */
export async function createIssue(
  actor: Actor,
  input: CreateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const project = requireFound(
    await projectRepo.findProjectById(input.orgId, input.projectId),
    "Project",
    input.projectId,
  );
  assertNotArchived("Project", project.id, project);
  assertCan(actor, "issue:create", projectResource(project));

  const org = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );
  const used = await issueRepo.countIssues(input.orgId, input.projectId);
  if (wouldExceedLimit(org.plan, "issuesPerProject", used)) {
    throw new Error(
      `Plan ${org.plan} allows no more issues in project ${project.key}`,
    );
  }

  const number = await issueRepo.nextIssueNumber(input.orgId, input.projectId);
  const issue = await issueRepo.insertIssue(input, actor.userId, number);

  await emit("issue.created", {
    ...actorEnvelope(actor),
    issueId: issue.id,
    projectId: issue.projectId,
    title: issue.title,
    assigneeId: issue.assigneeId,
    priority: issue.priority,
  });

  return issue;
}

export async function updateIssue(
  actor: Actor,
  input: UpdateIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.updateIssue(input);

  await emit("issue.updated", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    changedFields: Object.keys(input).filter(
      (key) => key !== "orgId" && key !== "issueId",
    ),
  });

  return after;
}

/** Status transitions are an `issue:update`, not a separate permission. */
export async function changeIssueStatus(
  actor: Actor,
  input: ChangeIssueStatusInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:update", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  if (before.status === input.status) return before;

  const after = await issueRepo.setIssueStatus(
    input.orgId,
    input.issueId,
    input.status,
  );

  await emit("issue.status_changed", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    from: before.status,
    to: after.status,
  });

  return after;
}

/**
 * Assignment has its own permission because a member may reassign work they
 * do not otherwise own. Un-assigning publishes `issue.updated` instead, since
 * `issue.assigned` carries a non-null assignee by contract.
 */
export async function assignIssue(
  actor: Actor,
  input: AssignIssueInput,
): Promise<Issue> {
  assertOrgScope(actor, input.orgId);

  const before = requireFound(
    await issueRepo.findIssueById(input.orgId, input.issueId),
    "Issue",
    input.issueId,
  );
  assertCan(actor, "issue:assign", issueResource(before));
  assertNotArchived("Issue", before.id, before);

  const after = await issueRepo.setIssueAssignee(
    input.orgId,
    input.issueId,
    input.assigneeId,
  );

  if (input.assigneeId === null) {
    await emit("issue.updated", {
      ...actorEnvelope(actor),
      issueId: after.id,
      projectId: after.projectId,
      changedFields: ["assigneeId"],
    });
    return after;
  }

  await emit("issue.assigned", {
    ...actorEnvelope(actor),
    issueId: after.id,
    projectId: after.projectId,
    previousAssigneeId: before.assigneeId,
    assigneeId: input.assigneeId,
  });

  return after;
}

export async function archiveIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<Issue> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:archive", issueResource(issue));
  assertNotArchived("Issue", issue.id, issue);

  const archived = await issueRepo.archiveIssue(orgId, issueId);

  await emit("issue.archived", {
    ...actorEnvelope(actor),
    issueId: archived.id,
    projectId: archived.projectId,
  });

  return archived;
}

/**
 * Board drag-and-drop. The index is presentation-only — the board renders by
 * `updated_at` — so a move is a status change plus a touch.
 */
export async function moveIssue(
  actor: Actor,
  input: MoveIssueInput,
): Promise<Issue> {
  return changeIssueStatus(actor, {
    orgId: input.orgId,
    issueId: input.issueId,
    status: input.toStatus,
  });
}

export async function getIssue(
  actor: Actor,
  orgId: OrgId,
  issueId: IssueId,
): Promise<IssueWithRelations> {
  assertOrgScope(actor, orgId);

  const issue = requireFound(
    await issueRepo.findIssueById(orgId, issueId),
    "Issue",
    issueId,
  );
  assertCan(actor, "issue:read", issueResource(issue));

  const labels = await labelRepo.listLabelsForIssues(orgId, [issue.id]);

  return {
    issue,
    labels: labels[issue.id] ?? [],
    commentCount: await commentRepo.countComments(orgId, issue.id),
    attachmentCount: (await attachmentRepo.listAttachments(orgId, issue.id))
      .length,
  };
}

export async function listIssues(
  actor: Actor,
  input: IssueFilterInput,
): Promise<Page<Issue>> {
/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}

/**
 * Wires every subscriber at process start. Called once from `src/instrumentation.ts`; the only module that knows the full listener set.
 *
 * Must call (do not reimplement): subscribe, registerActivityListeners, registerSearchListeners, registerUsageListeners, registerWebhookListeners
 */
import { subscribe } from "@/lib/event-bus";
import { createLogger } from "@/lib/logger";
import { enqueue } from "@/server/jobs/queue";
import { toIsoTimestamp } from "@/types/common";
import { registerActivityListeners } from "./activity-service";
import { registerSearchListeners } from "./search-service";
import { registerUsageListeners } from "./usage-service";
import { registerWebhookListeners } from "./webhook-service";
import type { Unsubscribe } from "@/types/event";

/**
 * Importing this module also loads `notification-service` transitively, which
 * attaches the notification fan-out on first import — that hub has no
 * `register*` entry point of its own.
 */
import "./notification-service";

const logger = createLogger("event-registry");

/** Non-null between `registerEventHandlers()` and `unregisterEventHandlers()`. */
let detach: Unsubscribe | null = null;

/**
 * Attaches every subscriber exactly once. Idempotent: `instrumentation.ts`
 * runs per server process, but a hot reload in dev can call it again and must
 * not double-deliver every event.
 */
export function registerEventHandlers(): void {
  if (detach !== null) return;

  const offs: Unsubscribe[] = [
    registerActivityListeners(),
    registerSearchListeners(),
    registerUsageListeners(),
    registerWebhookListeners(),
    registerDigestBridge(),
  ];

  detach = () => {
    for (const off of offs) off();
  };

  logger.info("event handlers registered", { groups: offs.length });
}

export function unregisterEventHandlers(): void {
  detach?.();
  detach = null;
}

/**
 * The one piece of wiring that belongs to no single service: turning a
 * `digest.due` event into a queued job. Keeping it here rather than inside
 * `DigestService` stops the service layer from depending on the job layer.
 */
function registerDigestBridge(): Unsubscribe {
  return subscribe("digest.due", (payload) => {
    enqueue({
      id: `digest:${payload.orgId}:${payload.recipientId}`,
      kind: "digest-email",
      runAt: toIsoTimestamp(new Date()),
      attempts: 0,
      payload: {
        orgId: payload.orgId,
        recipientId: payload.recipientId,
        windowStart: payload.windowStart,
      },
    });
  });
}
/**
 * Recomputes the usage counters that every `LimitCheck` compares against.
 *
 * Must call (do not reimplement): assertOrgScope, subscribe, getPlanLimits
 */
import { getPlanLimits } from "@/config/plan-limits";
import { emit, subscribe } from "@/lib/event-bus";
import { assertOrgScope } from "@/lib/tenant";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import type { OrgId } from "@/types/common";
import type { Unsubscribe } from "@/types/event";
import type { Actor } from "@/types/member";
import type { OrganizationUsage } from "@/types/organization";

/** Fraction of a quota at which the "approaching limit" event fires. */
const WARN_THRESHOLD = 0.9;

export async function getUsage(
  actor: Actor,
  orgId: OrgId,
): Promise<OrganizationUsage> {
  assertOrgScope(actor, orgId);
  return usageRepo.getUsage(orgId);
}

/**
 * Full recount from the source tables. Called by the rollup job and by every
 * event that could have moved a counter — after recounting, the seat and
 * project totals are checked against the plan so a breach surfaces as an
 * event rather than waiting for the next write to be rejected.
 */
export async function recomputeUsage(
  orgId: OrgId,
): Promise<OrganizationUsage> {
  const usage = await usageRepo.recomputeUsage(orgId);
  const org = await orgRepo.findOrgById(orgId);
  if (!org) return usage;

  const limits = getPlanLimits(org.plan);

  if (usage.seatsUsed >= limits.seats * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "seats",
      limit: limits.seats,
      used: usage.seatsUsed,
    });
  }

  if (usage.projectsUsed >= limits.projects * WARN_THRESHOLD) {
    await emit("billing.limit_exceeded", {
      orgId,
      actorId: null,
      occurredAt: toIsoTimestamp(new Date()),
      resource: "projects",
      limit: limits.projects,
      used: usage.projectsUsed,
    });
  }

  return usage;
}

/**
 * Every event that changes a counted resource nudges the cache. The deltas are
 * cheap; the periodic rollup is what corrects any drift they accumulate.
 */
export function registerUsageListeners(): Unsubscribe {
  const offs: Unsubscribe[] = [
    subscribe("issue.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: 1 });
    }),
    subscribe("issue.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { issuesUsed: -1 });
    }),
    subscribe("project.created", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { projectsUsed: 1 });
    }),
    subscribe("project.archived", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, {
        projectsUsed: -1,
        issuesUsed: -payload.issuesArchived,
      });
    }),
    subscribe("member.joined", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: 1 });
    }),
    subscribe("member.removed", async (payload) => {
      await usageRepo.incrementUsage(payload.orgId, { seatsUsed: -1 });
    }),
  ];

  return () => {
    for (const off of offs) off();
  };
}
/**
 * Label CRUD and the issue↔label assignment used by the picker.
 *
 * Must call (do not reimplement): assertCan, assertOrgScope
 */
import { assertCan } from "@/lib/permissions";
import { assertOrgScope } from "@/lib/tenant";
import * as labelRepo from "@/server/repositories/label-repository";
import { orgResource } from "./_support";
import type { CreateLabelInput, UpdateLabelInput } from "@/schemas/label";
import type { LabelId, OrgId } from "@/types/common";
import type { IssueLabel } from "@/types/issue";
import type { Actor } from "@/types/member";

/** Labels are org-wide metadata, so they follow the project permissions. */
export async function listLabels(
  actor: Actor,
  orgId: OrgId,
): Promise<readonly IssueLabel[]> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "project:read", orgResource(orgId));
  return labelRepo.listLabels(orgId);
}

export async function createLabel(
  actor: Actor,
  input: CreateLabelInput,
): Promise<IssueLabel> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:update", orgResource(input.orgId));

  const existing = await labelRepo.listLabels(input.orgId);
  if (existing.some((label) => label.name === input.name)) {
    throw new Error(`A label named "${input.name}" already exists`);
  }

  return labelRepo.insertLabel(input);
}

export async function updateLabel(
  actor: Actor,
  input: UpdateLabelInput,
): Promise<IssueLabel> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "project:update", orgResource(input.orgId));
  return labelRepo.updateLabel(input);
}

/**
 * Deleting a label detaches it from every issue. That is a wider blast radius
 * than the other label writes, so it takes the archive permission.
 */
export async function deleteLabel(
  actor: Actor,
  orgId: OrgId,
  labelId: LabelId,
): Promise<void> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "project:archive", orgResource(orgId));
  await labelRepo.deleteLabel(orgId, labelId);
}

import { z } from "zod";
import type { IssuePriority, IssueStatus } from "@/types/issue";
import {
  archiveScopeSchema,
  isoTimestampSchema,
  issueIdSchema,
  labelIdSchema,
  orgIdSchema,
  pageRequestSchema,
  projectIdSchema,
  userIdSchema,
} from "./common";

export const issueStatusSchema = z.enum([
  "backlog",
  "todo",
  "in_progress",
  "in_review",
  "done",
  "canceled",
]);

export const issuePrioritySchema = z.enum([
  "none",
  "low",
  "medium",
  "high",
  "urgent",
]);

export const createIssueSchema = z.object({
  orgId: orgIdSchema,
  projectId: projectIdSchema,
  title: z.string().min(3, "give the issue a title").max(200),
  description: z.string().max(20_000).nullable().default(null),
  status: issueStatusSchema.default("backlog"),
  priority: issuePrioritySchema.default("none"),
  assigneeId: userIdSchema.nullable().default(null),
  parentId: issueIdSchema.nullable().default(null),
  estimate: z.number().int().min(0).max(100).nullable().default(null),
  dueAt: isoTimestampSchema.nullable().default(null),
  labelIds: z.array(labelIdSchema).max(20).default([]),
});

export const updateIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  title: z.string().min(3).max(200).optional(),
  description: z.string().max(20_000).nullable().optional(),
  priority: issuePrioritySchema.optional(),
  estimate: z.number().int().min(0).max(100).nullable().optional(),
  dueAt: isoTimestampSchema.nullable().optional(),
  labelIds: z.array(labelIdSchema).max(20).optional(),
});

export const changeIssueStatusSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  status: issueStatusSchema,
});

export const assignIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  assigneeId: userIdSchema.nullable(),
});

export const archiveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
});

export const issueFilterSchema = z
  .object({
    orgId: orgIdSchema,
    projectId: projectIdSchema.optional(),
    status: z.array(issueStatusSchema).optional(),
    priority: z.array(issuePrioritySchema).optional(),
    assigneeId: userIdSchema.nullable().optional(),
    authorId: userIdSchema.optional(),
    labelIds: z.array(labelIdSchema).optional(),
    query: z.string().max(200).optional(),
    dueBefore: isoTimestampSchema.optional(),
  })
  .extend(pageRequestSchema.shape)
  .extend(archiveScopeSchema.shape);

/** Board drag-and-drop payload: move one issue into a column at an index. */
export const moveIssueSchema = z.object({
  orgId: orgIdSchema,
  issueId: issueIdSchema,
  toStatus: issueStatusSchema,
  toIndex: z.number().int().min(0),
});

const _statusParity: IssueStatus = "in_review" satisfies z.infer<
  typeof issueStatusSchema
>;
const _priorityParity: IssuePriority = "urgent" satisfies z.infer<
  typeof issuePrioritySchema
>;
void _statusParity;
void _priorityParity;

export type CreateIssueInput = z.infer<typeof createIssueSchema>;
export type UpdateIssueInput = z.infer<typeof updateIssueSchema>;
export type ChangeIssueStatusInput = z.infer<typeof changeIssueStatusSchema>;
export type AssignIssueInput = z.infer<typeof assignIssueSchema>;
export type IssueFilterInput = z.infer<typeof issueFilterSchema>;
export type MoveIssueInput = z.infer<typeof moveIssueSchema>;
import { z } from "zod";
import type {
  ActivityId,
  AttachmentId,
  CommentId,
  InvitationId,
  IsoTimestamp,
  IssueId,
  LabelId,
  MemberId,
  NotificationId,
  OrgId,
  ProjectId,
  SubscriptionId,
  UserId,
  WebhookId,
} from "@/types/common";

/**
 * Shared Zod primitives.
 *
 * Every schema in `src/schemas` is used twice: by `react-hook-form` through
 * `@hookform/resolvers/zod` on the client, and by the matching Server Action
 * on the server. Keep them free of server-only imports.
 */

const ULID = /^[0-9A-HJKMNP-TV-Z]{26}$/i;

/** Builds a branded-id schema whose output type is the branded alias. */
function brandedId<T extends string>(label: string) {
  return z
    .string()
    .regex(ULID, `${label} must be a ULID`)
    .transform((value) => value as T);
}

export const userIdSchema = brandedId<UserId>("userId");
export const orgIdSchema = brandedId<OrgId>("orgId");
export const projectIdSchema = brandedId<ProjectId>("projectId");
export const issueIdSchema = brandedId<IssueId>("issueId");
export const commentIdSchema = brandedId<CommentId>("commentId");
export const memberIdSchema = brandedId<MemberId>("memberId");
export const notificationIdSchema = brandedId<NotificationId>("notificationId");
export const activityIdSchema = brandedId<ActivityId>("activityId");
export const invitationIdSchema = brandedId<InvitationId>("invitationId");
export const labelIdSchema = brandedId<LabelId>("labelId");
export const attachmentIdSchema = brandedId<AttachmentId>("attachmentId");
export const subscriptionIdSchema = brandedId<SubscriptionId>("subscriptionId");
export const webhookIdSchema = brandedId<WebhookId>("webhookId");

export const isoTimestampSchema = z
  .iso
  .datetime()
  .transform((value) => value as IsoTimestamp);

export const emailSchema = z.email().max(254).toLowerCase();

export const sortDirectionSchema = z.enum(["asc", "desc"]);

export const pageRequestSchema = z.object({
  limit: z.number().int().min(1).max(100).default(25),
  cursor: z.string().nullable().optional(),
});

export const archiveScopeSchema = z.object({
  includeArchived: z.boolean().optional(),
});

export const hexColorSchema = z
  .string()
  .regex(/^#[0-9a-fA-F]{6}$/, "must be a #rrggbb color");

export type PageRequestInput = z.infer<typeof pageRequestSchema>;
export type ArchiveScopeInput = z.infer<typeof archiveScopeSchema>;
import type {
  AttachmentId,
  IsoTimestamp,
  IssueId,
  LabelId,
  ProjectId,
  SoftDeletable,
  TenantScoped,
  Timestamps,
  UserId,
} from "./common";

export type IssueStatus =
  | "backlog"
  | "todo"
  | "in_progress"
  | "in_review"
  | "done"
  | "canceled";

export const ISSUE_STATUSES: readonly IssueStatus[] = [
  "backlog",
  "todo",
  "in_progress",
