/** Inserts the entire import atomically; includes labels, issue rows and replay key. */
export async function insertIssueImport(input: ImportIssuesInput, authorId: UserId): Promise<IssueImportResult> {
  const db = getDb();
  const stamp = toIsoTimestamp(new Date());
  const run = db.transaction(() => {
    const existing = db.select().from(issueImports)
      .where(and(eq(issueImports.orgId, input.orgId), eq(issueImports.importKey, input.importKey))).get();
    if (existing) return null;

    const labelNames = [...new Set(input.rows.flatMap((row) => row.labels))];
    const knownLabels = db.select().from(labels).where(eq(labels.orgId, input.orgId)).all();
    const labelIds = new Map(knownLabels.map((label) => [label.name, label.id as LabelId]));
    for (const name of labelNames) {
      if (labelIds.has(name)) continue;
      const id = newId();
      db.insert(labels).values({ id, orgId: input.orgId, name, color: "#94a3b8", description: null, createdAt: stamp, updatedAt: stamp }).run();
      labelIds.set(name, id);
    }

    const emailToUser = new Map(db.select({ email: users.email, userId: users.id })
      .from(users).innerJoin(members, eq(members.userId, users.id))
      .where(and(eq(members.orgId, input.orgId), eq(members.status, "active"), isNull(members.archivedAt)))
      .all().map((row) => [row.email.toLowerCase(), row.userId as UserId]));
    const maximum = db.select({ value: sql<number | null>`max(${issues.number})` }).from(issues)
      .where(and(eq(issues.orgId, input.orgId), eq(issues.projectId, input.projectId))).get()?.value ?? 0;
    const created: Issue[] = [];
    input.rows.forEach((item, index) => {
      const id = newId() as IssueId;
      const row = db.insert(issues).values({
        id, orgId: input.orgId, projectId: input.projectId, number: maximum + index + 1,
        title: item.title, description: item.description, status: item.status, priority: item.priority,
        authorId, assigneeId: item.assigneeEmail === null ? null : emailToUser.get(item.assigneeEmail.toLowerCase()) ?? null,
        parentId: null, estimate: null, dueAt: item.dueAt,
        startedAt: null, completedAt: null, createdAt: stamp, updatedAt: stamp,
      }).returning().get();
      const ids = [...new Set(item.labels)].map((name) => labelIds.get(name)!).filter(Boolean);
      if (ids.length) db.insert(issueLabels).values(ids.map((labelId) => ({ orgId: input.orgId, issueId: id, labelId }))).run();
      created.push(toIssue(row, ids));
    });
    db.insert(issueImports).values({ orgId: input.orgId, importKey: input.importKey, projectId: input.projectId, issueIds: JSON.stringify(created.map((issue) => issue.id)), createdAt: stamp, updatedAt: stamp }).run();
    return { importKey: input.importKey, projectId: input.projectId, issues: created, replayed: false } satisfies IssueImportResult;
  });
  const result = run();
  return result ?? (await findIssueImport(input.orgId, input.importKey))!;
}

